        } else if self.dotenv {
            self.output_dotenv(final_env.unwrap().0, &redacted_keys)
        } else if self.values {
            self.output_values(&config, ts, &redacted_keys).await
        } else {
            self.output_shell(&config, ts, &redacted_keys).await
        }
    }

