    /// Implies `--jobs=1`
    #[usage(long, overrides = "jobs")]
    raw: bool,

    /// Remove the tool(s) from config file
    #[usage(long, value_name = "TOOL", aliases = ["rm", "unset"])]
    remove: Vec<BackendArg>,
}

