    let mut merged = IndexMap::new();
    for cf in config.config_files.values() {
        if let Some(bootstrap) = cf.bootstrap_config() {
            for (name, declaration) in bootstrap.secrets {
                merged.entry(name).or_insert(declaration);
            }
        }
    }
    merged
        .into_iter()
        .map(|(name, declaration)| declaration_from_toml(name, declaration))
        .collect()
}

pub(crate) fn statuses(config: &Config) -> Result<Vec<SecretStatus>> {
    Ok(declarations_from_config(config)?
        .into_iter()
        .map(|declaration| SecretStatus {
            state: env_state(&declaration),
            name: declaration.name,
            env: declaration.env,
            description: declaration.description,
        })
        .collect())
}

pub(crate) fn resolve(config: &Config, prompt: bool) -> Result<SecretValues> {
    let declarations = declarations_from_config(config)?
        .into_iter()
        .map(|declaration| (declaration.name.clone(), declaration))
        .collect();
    Ok(SecretValues {
        resolution: Arc::new(Mutex::new(SecretResolution {
            declarations,
            ..Default::default()
        })),
        prompt,
    })
}

impl SecretValues {
    pub(crate) fn used_statuses(&self) -> Result<Vec<SecretStatus>> {
        let resolution = self
            .resolution
            .lock()
            .map_err(|_| eyre::eyre!("bootstrap secret resolver is unavailable"))?;
        Ok(resolution
            .declarations
            .values()
            .filter(|declaration| {
                resolution.values.contains_key(&declaration.name)
                    || resolution.unavailable.contains_key(&declaration.name)
            })
            .map(|declaration| SecretStatus {
                state: if resolution.values.contains_key(&declaration.name) {
                    SecretState::Available
                } else {
                    env_state(declaration)
                },
                name: declaration.name.clone(),
                env: declaration.env.clone(),
                description: declaration.description.clone(),
            })
            .collect())
//! `[bootstrap.mise_shell_activate]` — declarative mise shell activation
//! snippets, applied by `mise bootstrap mise-shell-activate apply` or `mise bootstrap`.

use std::path::PathBuf;

use crate::file;
use crate::system::edits::{BlockSource, EditOp, EditRequest};
use crate::system::resources::ResourceOrigin;

#[derive(Debug, Clone)]
pub(crate) struct ShellActivationRequest {
    pub target: ShellActivationTarget,
    pub shell: ShellActivationShell,
    pub mode: ShellActivationMode,
    pub edit: EditRequest,
}

impl ShellActivationRequest {
    pub(crate) fn new(target: ShellActivationTarget, mode: ShellActivationMode) -> Self {
        let shell = target.shell();
        let target_raw = target.target_raw().to_string();
        Self {
            target,
            shell,
            mode,
            edit: EditRequest {
                path_raw: target_raw.clone(),
                path: file::replace_path(&target_raw),
                id: "activate".to_string(),
                op: EditOp::Block {
                    source: BlockSource::Inline(target.block(mode).to_string()),
                    template: false,
                    comment: "#".to_string(),
                },
                base: PathBuf::from("."),
                config_path: PathBuf::from("[bootstrap.mise_shell_activate]"),
                origin: ResourceOrigin {
                    config: PathBuf::from("[bootstrap.mise_shell_activate]"),
                    config_root: PathBuf::from("."),
                    environment: vec![],
                    source: None,
                },
            },
        }
    }
}

#[derive(Debug, Clone, Copy, Eq, PartialEq)]
pub(crate) enum ShellActivationMode {
    Activate,
    Shims,
}

impl ShellActivationMode {
    pub(crate) fn parse(value: &str) -> Option<Self> {
        match value {
            "activate" => Some(Self::Activate),
            "shims" => Some(Self::Shims),
            _ => None,
        }
    }

    pub(crate) fn name(self) -> &'static str {
        match self {
            Self::Activate => "activate",
            Self::Shims => "shims",
        }
    }
}

#[derive(Debug, Clone, Copy, Eq, Hash, PartialEq)]
pub(crate) enum ShellActivationShell {
    Bash,
    Zsh,
    Fish,
}

impl ShellActivationShell {
    pub(crate) fn parse(value: &str) -> Option<Self> {
        match value {
            "bash" => Some(Self::Bash),
            "zsh" => Some(Self::Zsh),
            "fish" => Some(Self::Fish),
            _ => None,
        }
    }

    pub(crate) fn default_targets(self) -> &'static [ShellActivationTarget] {
        match self {
            Self::Bash => &[
                ShellActivationTarget::BashProfile,
                ShellActivationTarget::Bashrc,
            ],
            Self::Zsh => &[
                ShellActivationTarget::Zprofile,
                ShellActivationTarget::Zshrc,
            ],
            Self::Fish => &[ShellActivationTarget::Fish],
        }
    }

    pub(crate) fn name(self) -> &'static str {
        match self {
            Self::Bash => "bash",
            Self::Zsh => "zsh",
            Self::Fish => "fish",
        }
