#[derive(Debug, Clone)]
pub(crate) struct ShellActivationRequest {
    pub target: ShellActivationTarget,
    pub shell: ShellActivationShell,
    pub mode: ShellActivationMode,
    pub edit: EditRequest,
}

impl ShellActivationRequest {
    pub(crate) fn new(target: ShellActivationTarget, mode: ShellActivationMode) -> Self {
        let shell = target.shell();
        let target_raw = target.target_raw().to_string();
        Self {
            target,
            shell,
            mode,
            edit: EditRequest {
                path_raw: target_raw.clone(),
                path: file::replace_path(&target_raw),
                id: "activate".to_string(),
                op: EditOp::Block {
                    source: BlockSource::Inline(target.block(mode).to_string()),
                    template: false,
                    comment: "#".to_string(),
                },
                base: PathBuf::from("."),
                config_path: PathBuf::from("[bootstrap.mise_shell_activate]"),
                origin: ResourceOrigin {
                    config: PathBuf::from("[bootstrap.mise_shell_activate]"),
                    config_root: PathBuf::from("."),
                    environment: vec![],
                    source: None,
                },
            },
        }
    }
}

#[derive(Debug, Clone, Copy, Eq, PartialEq)]
pub(crate) enum ShellActivationMode {
    Activate,
    Shims,
}

impl ShellActivationMode {
    pub(crate) fn parse(value: &str) -> Option<Self> {
        match value {
            "activate" => Some(Self::Activate),
            "shims" => Some(Self::Shims),
            _ => None,
        }
    }

    pub(crate) fn name(self) -> &'static str {
        match self {
            Self::Activate => "activate",
            Self::Shims => "shims",
        }
    }
}

#[derive(Debug, Clone, Copy, Eq, Hash, PartialEq)]
pub(crate) enum ShellActivationShell {
    Bash,
    Zsh,
    Fish,
}

impl ShellActivationShell {
    pub(crate) fn parse(value: &str) -> Option<Self> {
        match value {
            "bash" => Some(Self::Bash),
            "zsh" => Some(Self::Zsh),
            "fish" => Some(Self::Fish),
            _ => None,
        }
    }

    pub(crate) fn default_targets(self) -> &'static [ShellActivationTarget] {
        match self {
            Self::Bash => &[
                ShellActivationTarget::BashProfile,
                ShellActivationTarget::Bashrc,
            ],
            Self::Zsh => &[
                ShellActivationTarget::Zprofile,
                ShellActivationTarget::Zshrc,
            ],
            Self::Fish => &[ShellActivationTarget::Fish],
        }
    }

    pub(crate) fn name(self) -> &'static str {
        match self {
            Self::Bash => "bash",
            Self::Zsh => "zsh",
            Self::Fish => "fish",
        }
    }
}

