                        && !status.state.is_unavailable()
                })
                .collect::<Vec<_>>()
        } else {
            vec![]
        };
        let mut targets: Vec<_> = statuses
            .iter()
            .filter(|status| status.request.desired == PackageDesiredState::Present)
