	<"$BASE_DIR/packaging/standalone/install.envsubst"
addEventListener("fetch", (event) => {
  event.respondWith(handleRequest(event.request));
});

async function handleRequest(request) {
  async function MethodNotAllowed(request) {
    return new Response(`Method ${request.method} not allowed.`, {
      status: 405,
      headers: {
        Allow: "GET",
      },
    });
  }
  // Only GET requests work with this proxy.
  if (request.method !== "GET") return MethodNotAllowed(request);

  const url = new URL(request.url);
  const path = url.pathname;

  let targetUrl;

  // Route based on path
  switch (path) {
    case "/":
      targetUrl = "https://mise.jdx.dev/install.sh";
      break;
    case "/zsh":
      targetUrl = "https://mise.jdx.dev/mise.run/zsh";
      break;
    case "/bash":
      targetUrl = "https://mise.jdx.dev/mise.run/bash";
      break;
    case "/fish":
      targetUrl = "https://mise.jdx.dev/mise.run/fish";
      break;
    default:
      return new Response("Not found", { status: 404 });
  }

  const r = await fetch(targetUrl);
  const response = new Response(r.body, r);
  response.headers.set(
    "cache-control",
    "public, max-age=3600, s-maxage=3600, immutable",
  );
  response.headers.set("content-type", "text/plain");
  return response;
}
#!/bin/sh
set -eu

#region logging setup
if [ "${MISE_DEBUG-}" = "true" ] || [ "${MISE_DEBUG-}" = "1" ]; then
  debug() {
    echo "$@" >&2
  }
else
  debug() {
    :
  }
fi

if [ "${MISE_QUIET-}" = "1" ] || [ "${MISE_QUIET-}" = "true" ]; then
  info() {
    :
  }
else
  info() {
    echo "$@" >&2
  }
fi

error() {
  echo "$@" >&2
  exit 1
}
#endregion

install_mise() {
  # Download and install mise using the main install script
  info "mise: downloading and installing mise..."

  if [ -x "$(command -v curl)" ]; then
    curl -fsSL https://mise.jdx.dev/install.sh | sh
  elif [ -x "$(command -v wget)" ]; then
    wget -qO- https://mise.jdx.dev/install.sh | sh
  else
    error "mise install requires curl or wget but neither is installed. Aborting."
  fi

  install_path="${MISE_INSTALL_PATH:-$HOME/.local/bin/mise}"

